mapper.select:
SELECT
m.message_id,
m.conversation_id,
m.sender_user_id,
m.sender_type,
m.client_message_id,
m.content,
m.status,
m.created_at
FROM messages m
WHERE m.conversation_id = #{conversationId}


    AND (
    m.created_at < (
    SELECT created_at
    FROM messages
    WHERE message_id = #{beforeMessageId}
    )
    OR (
    m.created_at = (
    SELECT created_at
    FROM messages
    WHERE message_id = #{beforeMessageId}
    )
    AND m.message_id < #{beforeMessageId}
    )
    )


ORDER BY m.created_at DESC, m.message_id DESC
LIMIT #{limit}
